"""Package existing standard-article sources, reviewed previews and author drafts."""
from pathlib import Path
import hashlib,html,json,re,zipfile
from v4_submission import ROOT,OUT,plain
from v4_typeset import pdf_document,tconv

NOTE=ROOT/'notes/revision-v6'

def digest(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def dump(path,data):path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')

def main():
    metrics=json.loads((NOTE/'document-metrics.json').read_text())
    manuscript=json.loads((OUT/'manuscript-content.json').read_text())
    supplement=json.loads((OUT/'supplement-content.json').read_text())
    title=manuscript['title']
    title_doc={'title':title,'subtitle':'Title page for Journal of Forecasting; author completion required','abstract':'','sections':[{'title':'Author details','blocks':[
        {'type':'p','html':'Authors and affiliations: [TO BE COMPLETED BY AUTHOR].'},
        {'type':'p','html':'Corresponding author and contact: [TO BE COMPLETED BY AUTHOR].'},
        {'type':'p','html':'ORCID: [TO BE COMPLETED BY AUTHOR].'},
        {'type':'p','html':'Running title: Forecasting Position Peaks'},
        {'type':'p','html':'Funding: [TO BE COMPLETED BY AUTHOR].'},
        {'type':'p','html':'Conflict of interest: [TO BE COMPLETED BY AUTHOR].'},
        {'type':'p','html':"Study code and aggregate results: <a href='https://github.com/ByronLi0207/financial-mathematics-paper-20261020'>GitHub repository</a>."}]}],'references':[],'figures':[]}
    tex='\\documentclass[11pt,a4paper]{article}\n\\usepackage[margin=25mm]{geometry}\n\\usepackage[T1]{fontenc}\n\\usepackage[utf8]{inputenc}\n\\usepackage{hyperref}\n\\begin{document}\n\\section*{'+tconv(title)+'}\n'
    for b in title_doc['sections'][0]['blocks']:tex+=tconv(b['html'])+'\\par\\medskip\n'
    tex+='\\end{document}\n';(OUT/'title-page.tex').write_text(tex)
    title_pages=pdf_document(title_doc,OUT/'title-page-preview.pdf')
    (OUT/'main.tex').write_text('% Default main target. Select supplement.tex or title-page.tex separately.\n\\input{manuscript.tex}\n')
    # Preserve all existing union entries and append only the owning-proceedings
    # metadata for the new cited method. Existing bibliographic years are unchanged.
    bib=(OUT/'references.bib').read_text()
    if not re.search(r'@\w+\{gibbs2021,',bib):
        bib+='\n@inproceedings{gibbs2021,\n  author = {Gibbs, Isaac and Candes, Emmanuel},\n  title = {Adaptive Conformal Inference Under Distribution Shift},\n  booktitle = {Advances in Neural Information Processing Systems},\n  volume = {34},\n  pages = {1660--1672},\n  year = {2021},\n  url = {https://papers.nips.cc/paper/2021/hash/0d441de75945e5acbc865406fc9a2559-Abstract.html}\n}\n'
    (OUT/'references.bib').write_text(bib)
    (OUT/'cover-letter.md').write_text('Dear Editors of the Journal of Forecasting,\n\nPlease consider “'+title+'” as a research article. The study compares established forecasting procedures for a sampled absolute net-position peak with an issue-known floor, completed training labels and explicit history/update controls. Its elementary floor and construction properties, and the classical endpoint-to-peak bound, clarify the forecast object without claiming new probability inequalities or a universal forecasting method.\n\nThe original inspected FX comparison has lower stipulated quantile loss alongside more breach occasions; the separately fitted Treasury regression primary deteriorates. A source- and clock-controlled extension evaluates finite projected delayed ACI-style wrappers, a mature-headroom SAV adaptation inspired by CAViaR, and fixed mean/median combinations. These bounded adaptations are distinguished from their canonical method classes and guarantees. State-conditional diagnostics and target-level refits retain adverse outcomes, failed complete validation menus and insufficient-tail NA cases. The complete results and original primaries remain visible.\n\nThe contribution is evidence on the specified peak response, and the limits of transporting forecast rankings across measurement tasks. Historical, parsimonious, simulation, tail and forest controls give mixed outcomes. Related Treasury aggregates are not independent dealer replications, and the downloaded-vintage economic-date replay is not historical public-release validation. Compatible unseen-dealer and prospective evaluations, and an identified decision-cost mapping, remain outstanding. These forecast-object, evaluation and transport questions motivate the journal fit without presuming editorial acceptance.\n\nCode, source fingerprints, acquisition routes and aggregate outputs are available in the study repository. Raw FX inputs and private per-origin traces are not redistributed. New York Fed materials retain attribution and terms.\n\nAuthor identity, approval, funding, conflicts and required submission declarations: [TO BE COMPLETED BY AUTHOR]. This is a draft for author review; no journal submission or signed declaration has been made.\n\nSincerely,\n[TO BE COMPLETED BY AUTHOR]\n')
    (OUT/'AUTHOR-TODO.md').write_text('# 待用户决定与投稿前事项\n\n- 是否从已更新的 revision-v4-jof 分支新建 PR：当前未核到该 head 的既有 PR；不要改动独立 supervisor PR，也未合并 main。\n- 是否安装 TeX 或用现有外部编辑器导出正式 TeX PDF。当前随包 PDF 为 ReportLab 独立预览；应用内编译诊断通过也不等于已导出该正式 PDF。\n- 是否清理本任务 .bak/.scratch 缓存；本轮没有删除或移除文件，也没有触碰本地旧终版或其他项目。\n- 前瞻公共发布协议何时开始执行：需要先完成实际发布/issue-time 捕获适配，再在目标发布前留存有时间戳的预测；目前没有前瞻结果。\n- 由作者填写姓名、顺序、单位、联系信息、ORCID、基金、利益冲突和提交系统要求的个人声明；本任务未注册、投稿或代签。\n- 确认获取/使用权限、NYFed 归属和条款；免费读取不等于原数据可再分发。\n- 保留证据限制：兼容独立交易商样本、原始 release vintage 和决策成本映射仍缺失；上尾分位水平因既定失败或信息不足而不可评价，不应称其稳健性通过。\n- 期刊指南未核得数值字数/页数上限；9000 正文字、6 主表、4 主图是项目预算，并非已确认的期刊硬上限。按实际投稿时的最新要求再核对。\n')
    m=metrics['manuscript'];s=metrics['supplement']
    (OUT/'README.md').write_text('# Journal of Forecasting preparation package — revision v6\n\nThis is a research and submission-preparation package, not a journal submission or acceptance claim. Both original source-specific primaries and all archived adverse results are retained. All additional analyses are post-result / exploratory on previously inspected records.\n\n- manuscript.tex / manuscript-preview.pdf: '+str(m['pages'])+' independently typeset preview pages; '+str(m['prose_words_excluding_abstract_references_tables_captions'])+' prose words excluding abstract, references, tables and captions; '+str(m['tables'])+' tables and '+str(m['figures'])+' figures.\n- supplement.tex / supplement-preview.pdf: '+str(s['pages'])+' preview pages. Section S16 reports all finite delayed ACI-style, headroom SAV, fixed-combination, state and target-level inventories, including raw NA and adverse outcomes.\n- title-page.tex / title-page-preview.pdf: author-completion sheet, '+str(title_pages)+' page.\n- main.tex is the default article target. Select supplement.tex and title-page.tex separately.\n- references.bib retains the existing union metadata and adds the verified official ACI proceedings entry; displayed references are document-specific and alphabetized.\n- figures/ contains relative vector assets; no machine-specific font path is needed by the standard-article TeX.\n- cover-letter.md and AUTHOR-TODO.md are drafts for author review. No signed declarations, account registration or journal submission occurred.\n\nThe PDFs are ReportLab previews. The desktop built-in compiler checks saved TeX and returns diagnostics rather than an exported PDF. Compile, export and inspect formal TeX-generated PDFs before submission. A preview does not prove identical layout in another compiler. No system software was installed.\n\nBuild the v6 documents with v6_submission.py, render the separate previews with v6_typeset.py, run the extended v4_numeric.py consistency audit and package with v6_package.py. v6_supplement.py regenerates every new table from public aggregate outputs. New financial engines and workers are separate v6 modules; v6_tau_worker_v2.py is the canonical target-level transport wrapper, while its failed v1 technical attempt remains archived. Detailed protocol freezes, complete command outputs, resource receipts and audits are in protocol/revision-v6/ and notes/revision-v6/.\n\nExact code/aggregate consistency is not independent financial replication. FX acquisition and source fingerprints are documented in the repository; raw FX and private origin-level traces remain unshared. Treasury tasks are related aggregates, and their downloaded economic-date vintage is not an as-released public-information backtest. New short tail failures and all historical limitations remain explicit.\n')
    root_readme=ROOT/'README.md';old=root_readme.read_text();marker='## Journal of Forecasting preparation (revision v4)'
    if marker not in old:raise ValueError('DATED_README_BOUNDARY_MISSING')
    dated=old[old.index(marker):].replace('The merged-main guide follows below.','The dated merged-main historical guide follows below; its version labels describe that archived milestone.')
    intro='## Current Journal of Forecasting revision candidate (v6)\n\nThe current candidate is the [main manuscript](submission-jof/manuscript-preview.pdf) ('+str(m['pages'])+' preview pages), with the [complete Online Supplement](submission-jof/supplement-preview.pdf) ('+str(s['pages'])+' pages), [standard LaTeX/figure package](submission-jof/overleaf-package.zip), [v6 revision ledger](REVISION_V6_CHANGELOG.md) and [author checklist](submission-jof/AUTHOR-TODO.md). PDFs are separately typeset previews; formal TeX export remains distinct from built-in source diagnostics.\n\nThe original source primaries and all adverse archives remain unchanged. New finite delayed ACI-style wrappers, headroom SAV, fixed combinations, state diagnostics and target-level checks are post-result / exploratory; failures and upper-target NA remain explicit. Neither independent dealer validation, a canonical method guarantee nor journal acceptance is claimed. The preceding v5 source snapshots and audits remain under notes/revision-v6/ and notes/revision-v5-novelty/; earlier dated records follow below.\n\n'
    intro+='The [v6 reproduction guide](protocol/revision-v6/REPLAY.md) separates public document regeneration from exact-byte private-input financial replay. The standard-library setup helper validates and prepares a new isolated tree without fitting models; it does not supply missing private data or bypass frozen gates.\n\n'
    root_readme.write_text(intro+dated)
    included=[OUT/x for x in ['main.tex','manuscript.tex','supplement.tex','title-page.tex','references.bib','README.md','cover-letter.md','AUTHOR-TODO.md']]+sorted((OUT/'figures').glob('*.pdf'))
    with zipfile.ZipFile(OUT/'overleaf-package.zip','w',zipfile.ZIP_DEFLATED) as z:
        for file in included:z.write(file,file.relative_to(OUT))
    with zipfile.ZipFile(OUT/'overleaf-package.zip') as z:
        assert z.testzip() is None
        assert all(not x.startswith('/') and '..' not in Path(x).parts for x in z.namelist())
        for file in included:assert z.read(str(file.relative_to(OUT)))==file.read_bytes()
    manifest={'files':{str(p.relative_to(OUT)):digest(p) for p in included},'sha256':digest(OUT/'overleaf-package.zip'),'targets':['main.tex','supplement.tex','title-page.tex'],'absolute_asset_paths':False,'title_preview_pages':title_pages}
    dump(NOTE/'overleaf-manifest.json',manifest)
    print(json.dumps({'status':'PACKAGE_EXACT_BYTE_VERIFIED','source_file_count':len(included),'title_pages':title_pages,'zip_sha256':manifest['sha256']}))
if __name__=='__main__':main()
